 private void setup(){screenKind="setup";screen("Connect to Mythic Reverie");EditText address=new EditText(this);address.setText(base);address.setHint("https://your-server or http://10.50.100.235:5922");address.setTextColor(Color.WHITE);address.setSingleLine(true);content.addView(address);button("Connect",()->{try{URI u=new URI(address.getText().toString().trim());String host=u.getHost();if(host==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||(!u.getPath().isEmpty()&&!u.getPath().equals("/")))throw new Exception("Enter your server address without a path");boolean local=host.equals("localhost")||host.equals("127.0.0.1");String[] octets=host.split("\\.");if(octets.length==4){try{int[] ip=new int[4];boolean valid=true;for(int i=0;i<4;i++){ip[i]=Integer.parseInt(octets[i]);if(ip[i]<0||ip[i]>255)valid=false;}local=local||(valid&&(ip[0]==10||(ip[0]==192&&ip[1]==168)||(ip[0]==172&&ip[1]>=16&&ip[1]<=31)));}catch(NumberFormatException ignored){}};if(!u.getScheme().equals("https")&&!(u.getScheme().equals("http")&&local))throw new Exception("Use HTTPS for a public server");base=u.getScheme()+"://"+u.getRawAuthority();prefs.edit().putString("server",base).remove("token").remove("tokenServer").apply();token="";pairCode="";pollSecret="";pair();}catch(Exception e){message.setText(e.getMessage());}});}
 private void request(String path,String method,JSONObject data,Result result){final String requestBase=base,requestToken=token;final int requestScreen=screenVersion;network.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(requestBase+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(path.equals("/api/tv-native/play")?120000:30000);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(!requestToken.isEmpty())c.setRequestProperty("Authorization","Bearer "+requestToken);if(data!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(in!=null)try(in){byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){bytes.write(block,0,n);if(bytes.size()>2*1024*1024)throw new Exception("Server response too large");}}c.disconnect();JSONObject json=new JSONObject(bytes.toString("UTF-8"));if(code>=300)throw new Exception(json.optString("error","Request failed ("+code+")"));ui.post(()->{if(stopped||requestScreen!=screenVersion||!requestBase.equals(base))return;try{result.accept(json);}catch(Exception e){message.setText(e.getMessage());}});}catch(Exception e){ui.post(()->{if(!stopped&&requestScreen==screenVersion&&requestBase.equals(base)&&message!=null)message.setText(e.getMessage());});}});}
