 private void beginPasswordLogin(){message.setText("Preparing secure sign-in...");request("/api/tv-native/pair/start","POST",object("name",Build.MANUFACTURER+" "+Build.MODEL),r->{pairCode=r.getString("code");pollSecret=r.getString("pollSecret");signIn();});}
