 private void pairQr(String url){try{com.google.zxing.common.BitMatrix matrix=new com.google.zxing.qrcode.QRCodeWriter().encode(url,com.google.zxing.BarcodeFormat.QR_CODE,360,360);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(360,360,android.graphics.Bitmap.Config.ARGB_8888);for(int y=0;y<360;y++)for(int x=0;x<360;x++)bitmap.setPixel(x,y,matrix.get(x,y)?Color.BLACK:Color.WHITE);ImageView code=new ImageView(this);code.setImageBitmap(bitmap);code.setContentDescription("Scan this QR code to connect Mythic Reverie TV");content.addView(code,2,new LinearLayout.LayoutParams(dp(220),dp(220)));}catch(Exception ignored){}}
 private String loginCookie="";
 private void sessionRequest(String path,JSONObject body,Result callback){final String server=base;final String cookie=loginCookie;final int version=screenVersion;network.execute(()->{HttpURLConnection c=null;try{if(!server.startsWith("https://"))throw new Exception("Password sign-in requires HTTPS. Use phone pairing for a local HTTP server.");c=(HttpURLConnection)new URL(server+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestMethod(body==null?"GET":"POST");c.setRequestProperty("Accept","application/json");if(!cookie.isEmpty())c.setRequestProperty("Cookie",cookie);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int status=c.getResponseCode();String receivedCookie=c.getHeaderField("Set-Cookie");if(receivedCookie!=null&&receivedCookie.startsWith("io_session="))loginCookie=receivedCookie.split(";",2)[0];ByteArrayOutputStream data=new ByteArrayOutputStream();InputStream source=status<400?c.getInputStream():c.getErrorStream();if(source!=null)try(InputStream in=source){byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){data.write(block,0,n);if(data.size()>1024*1024)throw new Exception("Response too large");}}Object value=new JSONTokener(data.toString("UTF-8")).nextValue();JSONObject result=value instanceof JSONArray?object("profiles",value):(JSONObject)value;if(status>=300)throw new Exception(result.optString("error","Sign-in request failed"));ui.post(()->{if(stopped||version!=screenVersion||!server.equals(base))return;try{callback.accept(result);}catch(Exception e){message.setText(e.getMessage());}});}catch(Exception e){ui.post(()->{if(!stopped&&version==screenVersion&&server.equals(base))message.setText(e.getMessage());});}finally{if(c!=null)c.disconnect();}});}
 private EditText field(String hint,boolean secret){EditText input=new EditText(this);input.setHint(hint);input.setTextColor(Color.WHITE);input.setHintTextColor(Color.LTGRAY);input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(secret?android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:android.text.InputType.TYPE_TEXT_VARIATION_NORMAL));if(Build.VERSION.SDK_INT>=26)input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);input.setSaveEnabled(false);content.addView(input);return input;}
 private void signIn(){getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);screenKind="login";screen("Welcome to Mythic Reverie");message.setText("Every story, your way.\nSign in with your Mythic Reverie username.");EditText username=field("Username",false),password=field("Password",true),code=field("Two-factor code (if enabled)",false);button("Sign in",()->{String name=username.getText().toString(),pass=password.getText().toString(),totp=code.getText().toString();sessionRequest("/api/auth/login",object("username",name,"password",pass,"totpCode",totp),r->{if(r.optBoolean("requiresTotp")){message.setText("Enter your two-factor authentication code, then sign in again.");code.requestFocus();return;}password.setText("");code.setText("");chooseLoginProfile();});});button("Use QR code instead",()->{logoutLoginSession();pair();});authLayout();username.requestFocus();}
