 private final android.util.LruCache<String,android.graphics.Bitmap> artworkCache=new android.util.LruCache<String,android.graphics.Bitmap>(16*1024*1024){protected int sizeOf(String k,android.graphics.Bitmap v){return v.getByteCount();}};
 private void loadArtwork(ImageView image,String asset){image.setImageResource(R.drawable.io_mark);if(asset==null||!asset.startsWith("/media-asset/")||asset.contains(".."))return;final int imageVersion=screenVersion;final boolean thumbnail=image.getLayoutParams()!=null&&image.getLayoutParams().height>0;final String imageBase=base,imageToken=token,key=base+asset+(thumbnail?":thumb":":large");image.setTag(key);android.graphics.Bitmap cached=artworkCache.get(key);if(cached!=null){image.setImageBitmap(cached);return;}artworkNetwork.execute(()->{if(imageVersion!=screenVersion)return;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(imageBase+asset).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestProperty("Authorization","Bearer "+imageToken);if(c.getResponseCode()!=200)return;ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){data.write(buf,0,n);if(data.size()>8*1024*1024)return;}}byte[] bytes=data.toByteArray();android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>(thumbnail?320:1280)||options.outHeight/options.inSampleSize>(thumbnail?480:720))options.inSampleSize*=2;if(thumbnail)options.inPreferredConfig=android.graphics.Bitmap.Config.RGB_565;options.inJustDecodeBounds=false;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap!=null){artworkCache.put(key,bitmap);ui.post(()->{if(key.equals(image.getTag())&&imageBase.equals(base)&&imageToken.equals(token)&&!isDestroyed())image.setImageBitmap(bitmap);});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}});}
