 private void playLive(String id){
  screen("Opening channel...");request("/api/tv-native/iptv/channels/"+enc(id)+"/play","GET",null,r->{
   // Provider requests must never receive the Mythic device bearer token.
   DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setConnectTimeoutMs(15000).setReadTimeoutMs(30000);
   player=new ExoPlayer.Builder(this).setMediaSourceFactory(new DefaultMediaSourceFactory(http)).build();
   player.setAudioAttributes(new androidx.media3.common.AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);player.setHandleAudioBecomingNoisy(true);PlayerView view=new PlayerView(this);view.setPlayer(player);view.setKeepScreenOn(true);view.setControllerShowTimeoutMs(3500);setContentView(view);screenKind="live-player";
   player.setMediaItem(MediaItem.fromUri(r.getString("url")));player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException error){Toast.makeText(MainActivity.this,"Channel unavailable: "+error.getErrorCodeName(),Toast.LENGTH_LONG).show();liveChannels("","",0);}});
   player.prepare();player.play();view.requestFocus();
  });
 }
