 private android.app.AlertDialog nextEpisodeDialog; private Runnable autoplayTick; private int autoplayGeneration; private boolean endHandled;
 private void cancelNextEpisode(){autoplayGeneration++;if(autoplayTick!=null){ui.removeCallbacks(autoplayTick);autoplayTick=null;}android.app.AlertDialog dialog=nextEpisodeDialog;nextEpisodeDialog=null;if(dialog!=null)dialog.dismiss();}
 private void episodeEnded(){if(endHandled||stopped||!screenKind.equals("player"))return;endHandled=true;saveProgress();if(!prefs.getBoolean("autoplayNext",true))return;final String id=playingId,current=playingEpisode;request("/api/tv-native/title/"+enc(id),"GET",null,r->{if(stopped||player==null||player.getPlaybackState()!=Player.STATE_ENDED||!prefs.getBoolean("autoplayNext",true)||!screenKind.equals("player")||!id.equals(playingId)||!current.equals(playingEpisode))return;JSONArray episodes=r.optJSONArray("episodes");if(episodes==null)return;for(int i=0;i<episodes.length();i++){JSONObject episode=episodes.optJSONObject(i);if(episode!=null&&current.equals(episode.optString("path"))){if(i+1<episodes.length()){JSONObject next=episodes.getJSONObject(i+1);offerNextEpisode(id,next.optString("path"),next.optString("title"));}else Toast.makeText(this,"You have reached the end of this title.",Toast.LENGTH_LONG).show();return;}}});}
 private void offerNextEpisode(String id,String episode,String title){cancelNextEpisode();final int generation=autoplayGeneration;final int[] remaining={8};Runnable launch=()->{if(generation!=autoplayGeneration||stopped||!screenKind.equals("player"))return;cancelNextEpisode();playOptions(id,episode,0);};nextEpisodeDialog=new android.app.AlertDialog.Builder(this).setTitle("Up Next: "+title).setMessage("Starting in 8 seconds").setPositiveButton("Play now",(dialog,which)->launch.run()).setNegativeButton("Cancel",(dialog,which)->cancelNextEpisode()).setOnCancelListener(dialog->cancelNextEpisode()).create();nextEpisodeDialog.setOnDismissListener(dialog->{if(nextEpisodeDialog==dialog)cancelNextEpisode();});nextEpisodeDialog.show();autoplayTick=new Runnable(){public void run(){if(generation!=autoplayGeneration||nextEpisodeDialog==null||stopped)return;if(--remaining[0]<=0){launch.run();return;}nextEpisodeDialog.setMessage("Starting in "+remaining[0]+" seconds");ui.postDelayed(this,1000);}};ui.postDelayed(autoplayTick,1000);}
 private String audioOutputStatus="Playback has not started"; private boolean directPlayback=false,forceSdr=false; private String selectedQuality="original"; private Integer selectedAudio=null,selectedSubtitle=null; private JSONObject playbackTracks=new JSONObject();
 private String language(String code){String c=code.toLowerCase(Locale.ROOT);if(c.equals("en")||c.equals("eng"))return "English";if(c.equals("ja")||c.equals("jpn"))return "Japanese";if(c.equals("und")||c.isEmpty())return "Unspecified language";return new Locale(c).getDisplayLanguage(Locale.ENGLISH);}
 private String normalized(String code){if(code.equalsIgnoreCase("eng"))return "en";if(code.equalsIgnoreCase("jpn"))return "ja";return code.toLowerCase(Locale.ROOT);}
 private Integer preferredTrack(JSONArray tracks,String preferred,boolean subtitles){if(tracks==null||preferred.equals("off"))return null;for(int i=0;i<tracks.length();i++){JSONObject track=tracks.optJSONObject(i);if(track!=null&&(!subtitles||track.optBoolean("supported",true))&&normalized(track.optString("language")).equals(normalized(preferred)))return track.optInt("index");}return null;}
