 private void audioSettings(){
  final String[] modes={"auto","stereo","night"};
  final String[] names={"Auto / original surround (receiver)","Stereo compatibility (AAC)","Night mode (quieter peaks, stereo)"};
  int checked=Arrays.asList(modes).indexOf(prefs.getString("audioMode","auto"));
  new android.app.AlertDialog.Builder(this).setTitle("Sound / AV receiver").setSingleChoiceItems(names,checked,(dialog,which)->{
   prefs.edit().putString("audioMode",modes[which]).apply();dialog.dismiss();
   if(player!=null&&screenKind.equals("player")){double at=(offset+player.getCurrentPosition())/1000.0;forceSdr=false;play(playingId,playingEpisode,at);}else Toast.makeText(this,"Sound preference saved for library playback",Toast.LENGTH_LONG).show();
  }).setNeutralButton("Sound information",(dialog,which)->new android.app.AlertDialog.Builder(this).setTitle("Receiver audio").setMessage(audioOutputStatus+"\n\nChoose Original video quality for original audio. Atmos requires an Atmos source, compatible TV/device, receiver and HDMI settings. Android negotiates output; check the receiver display to confirm Atmos.\n\nStereo and Night mode convert audio and do not preserve Atmos. They can also require HDR-to-SDR conversion. These modes apply to library videos, not IPTV.\n\nTHX processing must be configured on supported receiver equipment; this app does not implement THX.").setPositiveButton("Back",(d,w)->audioSettings()).show()).setNegativeButton("Close",(dialog,which)->{if(player!=null)player.play();}).setOnCancelListener(dialog->{if(player!=null)player.play();}).show();
 }
 private void chooseQuality(){String[] values={"original","1080","720","480","360"};new android.app.AlertDialog.Builder(this).setTitle("Video quality").setSingleChoiceItems(values,Arrays.asList(values).indexOf(selectedQuality),(dialog,which)->{dialog.dismiss();double at=(offset+player.getCurrentPosition())/1000.0;selectedQuality=values[which];forceSdr=false;prefs.edit().putString("quality",selectedQuality).apply();play(playingId,playingEpisode,at);}).setNegativeButton("Back",(dialog,which)->trackMenu()).setOnCancelListener(dialog->{if(player!=null)player.play();}).show();}
 private void chooseTrack(boolean subtitles){JSONArray tracks=playbackTracks.optJSONArray(subtitles?"subtitles":"audio");ArrayList<String> labels=new ArrayList<>();ArrayList<JSONObject> choices=new ArrayList<>();labels.add(subtitles?"Off":"Default audio");choices.add(null);int checked=0;Integer selected=subtitles?selectedSubtitle:selectedAudio;if(tracks!=null)for(int i=0;i<tracks.length();i++){JSONObject t=tracks.optJSONObject(i);if(t==null)continue;if(subtitles&&!t.optBoolean("supported",true))continue;choices.add(t);String title=t.optString("title","");labels.add(language(t.optString("language"))+(title.isEmpty()?"":" - "+title)+(subtitles?"":" | "+t.optString("codec").toUpperCase()+" | "+t.optInt("channels",0)+" channels"+(t.optString("profile").isEmpty()?"":" | "+t.optString("profile"))));if(selected!=null&&selected==t.optInt("index"))checked=choices.size()-1;}if(choices.size()==1){Toast.makeText(this,subtitles?"No text subtitle tracks are available. Image-based subtitles are not supported yet.":"No alternate audio tracks are available in this file.",Toast.LENGTH_LONG).show();if(player!=null)player.play();return;}
  new android.app.AlertDialog.Builder(this).setTitle(subtitles?"Subtitle language":"Audio language").setSingleChoiceItems(labels.toArray(new String[0]),checked,(dialog,which)->{dialog.dismiss();if(player==null)return;double at=(offset+player.getCurrentPosition())/1000.0;JSONObject track=choices.get(which);Integer index=track==null?null:track.optInt("index");if(subtitles){selectedSubtitle=index;prefs.edit().putString("subtitleLanguage",track==null?"off":normalized(track.optString("language"))).apply();}else{selectedAudio=index;prefs.edit().putString("audioLanguage",track==null?"default":normalized(track.optString("language"))).apply();}play(playingId,playingEpisode,at);}).setNegativeButton("Back",(dialog,which)->trackMenu()).setOnCancelListener(dialog->{if(player!=null)player.play();}).show();
 }

 private JSONObject hdrCapabilities(){
  JSONObject result=new JSONObject();JSONArray video=new JSONArray(),audio=new JSONArray(),profiles=new JSONArray();
  try{
   boolean hdr10=false,hlg=false,dv=false;
   if(android.os.Build.VERSION.SDK_INT>=24){for(int type:getWindowManager().getDefaultDisplay().getHdrCapabilities().getSupportedHdrTypes()){if(type==android.view.Display.HdrCapabilities.HDR_TYPE_HDR10)hdr10=true;if(type==android.view.Display.HdrCapabilities.HDR_TYPE_HLG)hlg=true;if(type==android.view.Display.HdrCapabilities.HDR_TYPE_DOLBY_VISION)dv=true;}}
   JSONObject source=playbackTracks.optJSONObject("video");int width=source==null?0:source.optInt("width"),height=source==null?0:source.optInt("height");
   for(android.media.MediaCodecInfo codec:new android.media.MediaCodecList(android.media.MediaCodecList.REGULAR_CODECS).getCodecInfos()){
    if(codec.isEncoder())continue;
    for(String mime:codec.getSupportedTypes())try{
     android.media.MediaCodecInfo.CodecCapabilities cap=codec.getCapabilitiesForType(mime);
     if(mime.startsWith("video/")&&width>0&&height>0&&cap.getVideoCapabilities()!=null&&!cap.getVideoCapabilities().isSizeSupported(width,height))continue;
     if(mime.equals("video/hevc")){for(android.media.MediaCodecInfo.CodecProfileLevel pl:cap.profileLevels)if(pl.profile==android.media.MediaCodecInfo.CodecProfileLevel.HEVCProfileMain10||pl.profile==android.media.MediaCodecInfo.CodecProfileLevel.HEVCProfileMain10HDR10||pl.profile==android.media.MediaCodecInfo.CodecProfileLevel.HEVCProfileMain10HDR10Plus){video.put("hevc");break;}}if(mime.equals("video/avc"))video.put("h264");if(mime.equals("video/x-vnd.on2.vp9"))video.put("vp9");if(mime.equals("video/av01"))video.put("av1");
     if(mime.equals("video/dolby-vision")){for(android.media.MediaCodecInfo.CodecProfileLevel pl:cap.profileLevels){if(pl.profile==android.media.MediaCodecInfo.CodecProfileLevel.DolbyVisionProfileDvheStn)profiles.put(5);if(pl.profile==android.media.MediaCodecInfo.CodecProfileLevel.DolbyVisionProfileDvheSt)profiles.put(8);}}
     if(mime.equals("audio/mp4a-latm"))audio.put("aac");if(mime.equals("audio/ac3"))audio.put("ac3");if(mime.equals("audio/eac3"))audio.put("eac3");if(mime.equals("audio/opus"))audio.put("opus");if(mime.equals("audio/flac"))audio.put("flac");if(mime.equals("audio/mpeg"))audio.put("mp3");
    }catch(Exception ignored){}
   }
   if(android.os.Build.VERSION.SDK_INT>=29){
    JSONArray tracks=playbackTracks.optJSONArray("audio");JSONObject chosen=null;
    if(tracks!=null)for(int n=0;n<tracks.length();n++){JSONObject track=tracks.optJSONObject(n);if(chosen==null||selectedAudio!=null&&track.optInt("index")==selectedAudio)chosen=track;}
    int channels=chosen==null?6:chosen.optInt("channels",6),sampleRate=chosen==null?48000:chosen.optInt("sampleRate",48000);if(sampleRate<=0)sampleRate=48000;
    int mask=channels>=8?android.media.AudioFormat.CHANNEL_OUT_7POINT1_SURROUND:channels>=6?android.media.AudioFormat.CHANNEL_OUT_5POINT1:android.media.AudioFormat.CHANNEL_OUT_STEREO;
    android.media.AudioAttributes attr=new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_MOVIE).build();
    int[] formats={android.media.AudioFormat.ENCODING_AC3,android.media.AudioFormat.ENCODING_E_AC3,android.media.AudioFormat.ENCODING_E_AC3_JOC,android.media.AudioFormat.ENCODING_DOLBY_TRUEHD,android.media.AudioFormat.ENCODING_DTS,android.media.AudioFormat.ENCODING_DTS_HD};String[] codecs={"ac3","eac3","eac3","truehd","dts","dts"};
    for(int n=0;n<formats.length;n++)try{android.media.AudioFormat format=new android.media.AudioFormat.Builder().setEncoding(formats[n]).setSampleRate(sampleRate).setChannelMask(mask).build();if(android.media.AudioTrack.isDirectPlaybackSupported(format,attr))audio.put(codecs[n]);}catch(Exception ignored){}
   }
   result.put("hdr10",hdr10).put("hlg",hlg).put("dolbyVision",dv).put("videoCodecs",video).put("audioCodecs",audio).put("dvProfiles",profiles);
  }catch(Exception ignored){}return result;
 }
 private void applyOriginalTracks(androidx.media3.common.Tracks tracks){
  if(player==null)return;
  androidx.media3.common.TrackSelectionParameters.Builder params=player.getTrackSelectionParameters().buildUpon();
  params.clearOverridesOfType(C.TRACK_TYPE_AUDIO).clearOverridesOfType(C.TRACK_TYPE_TEXT).setTrackTypeDisabled(C.TRACK_TYPE_TEXT,selectedSubtitle==null);
  for(int type:new int[]{C.TRACK_TYPE_AUDIO,C.TRACK_TYPE_TEXT}){
   Integer selected=type==C.TRACK_TYPE_AUDIO?selectedAudio:selectedSubtitle;if(selected==null)continue;
   JSONArray items=playbackTracks.optJSONArray(type==C.TRACK_TYPE_AUDIO?"audio":"subtitles");int wanted=-1;
   if(items!=null)for(int n=0;n<items.length();n++)if(items.optJSONObject(n).optInt("index")==selected)wanted=n;
   int ordinal=0;
   for(androidx.media3.common.Tracks.Group group:tracks.getGroups())if(group.getType()==type){for(int i=0;i<group.length;i++){if(ordinal++==wanted&&group.isTrackSupported(i))params.setOverrideForType(new androidx.media3.common.TrackSelectionOverride(group.getMediaTrackGroup(),i));}}
  }
  androidx.media3.common.TrackSelectionParameters updated=params.build();if(!updated.equals(player.getTrackSelectionParameters()))player.setTrackSelectionParameters(updated);
 }
 private boolean styledSubtitle(){JSONArray tracks=playbackTracks.optJSONArray("subtitles");if(selectedSubtitle==null||tracks==null)return false;for(int i=0;i<tracks.length();i++){JSONObject t=tracks.optJSONObject(i);if(t!=null&&t.optInt("index")==selectedSubtitle&&("ass".equals(t.optString("codec"))||"ssa".equals(t.optString("codec"))))return true;}return false;}
 private void play(String id,String episode,double start){endHandled=false;screen("Preparing playback...");request("/api/tv-native/play","POST",object("id",id,"episode",episode,"offset",start,"quality",selectedQuality,"capabilities",hdrCapabilities(),"audioMode",prefs.getString("audioMode","auto"),"forceSdr",forceSdr,"audio",selectedAudio==null?JSONObject.NULL:selectedAudio,"subtitle",styledSubtitle()?selectedSubtitle:JSONObject.NULL),r->{audioOutputStatus=r.optString("audioOutput","Output not reported by server");directPlayback="direct".equals(r.optString("mode"));playingId=id;playingEpisode=episode;offset=(long)(r.optDouble("startOffsetSeconds",0)*1000);DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setConnectTimeoutMs(15000).setReadTimeoutMs(120000).setDefaultRequestProperties(Collections.singletonMap("Authorization","Bearer "+token));player=new ExoPlayer.Builder(this).setMediaSourceFactory(new DefaultMediaSourceFactory(http)).setSeekBackIncrementMs(10000).setSeekForwardIncrementMs(10000).build();player.setAudioAttributes(new androidx.media3.common.AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);player.setHandleAudioBecomingNoisy(true);PlayerView view=new PlayerView(this);view.setPlayer(player);view.setKeepScreenOn(true);FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(Color.BLACK);frame.addView(view,new FrameLayout.LayoutParams(-1,-1));Button tracks=action("Audio / Subtitles",this::trackMenu);FrameLayout.LayoutParams menuLayout=new FrameLayout.LayoutParams(dp(190),dp(44),Gravity.TOP|Gravity.END);menuLayout.setMargins(dp(12),dp(12),dp(12),0);frame.addView(tracks,menuLayout);tracks.setVisibility(View.GONE);view.setControllerShowTimeoutMs(3500);view.setControllerVisibilityListener((PlayerView.ControllerVisibilityListener)visibility->tracks.setVisibility(visibility));setContentView(frame);MediaItem.Builder media=new MediaItem.Builder().setUri(base+r.getString("playlistUrl"));if(!directPlayback&&selectedSubtitle!=null&&!r.optBoolean("subtitleBurnedIn")){String url=base+"/api/tv-native/subtitle?id="+enc(id)+"&episode="+enc(episode)+"&track="+selectedSubtitle+"&shift="+(offset/1000.0);MediaItem.SubtitleConfiguration subtitle=new MediaItem.SubtitleConfiguration.Builder(android.net.Uri.parse(url)).setMimeType(MimeTypes.TEXT_VTT).setSelectionFlags(C.SELECTION_FLAG_DEFAULT).build();media.setSubtitleConfigurations(Collections.singletonList(subtitle));}player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setTrackTypeDisabled(C.TRACK_TYPE_TEXT,selectedSubtitle==null).build());player.setMediaItem(media.build());if(directPlayback)player.seekTo((long)(r.optDouble("seekSeconds",0)*1000));Toast.makeText(this,r.optString("dynamicRange","SDR")+(directPlayback?" - Original playback":" - Converted playback"),Toast.LENGTH_LONG).show();screenKind="player";player.addListener(new Player.Listener(){@Override public void onTracksChanged(androidx.media3.common.Tracks tracks){if(directPlayback)applyOriginalTracks(tracks);}@Override public void onPlaybackStateChanged(int state){if(state==Player.STATE_ENDED)episodeEnded();}@Override public void onPlayerError(PlaybackException error){if(directPlayback&&!forceSdr&&error.errorCode>=3000&&error.errorCode<6000){double at=player.getCurrentPosition()/1000.0;forceSdr=true;Toast.makeText(MainActivity.this,"Device cannot play the original. Trying SDR conversion...",Toast.LENGTH_LONG).show();play(id,episode,Math.max(start,at));return;}Toast.makeText(MainActivity.this,"Playback failed: "+error.getErrorCodeName(),Toast.LENGTH_LONG).show();title(playingId);}});player.prepare();player.play();view.hideController();view.requestFocus();ui.postDelayed(this::progressTick,15000);});}
 @Override public boolean onKeyDown(int key,KeyEvent event){if(screenKind.equals("player")&&(key==KeyEvent.KEYCODE_MENU||key==KeyEvent.KEYCODE_CAPTIONS)){trackMenu();return true;}return super.onKeyDown(key,event);}
 private void progressTick(){if(player==null||stopped)return;saveProgress();ui.postDelayed(this::progressTick,15000);}
 private void saveProgress(){if(player==null||!screenKind.equals("player")||player.getDuration()<=0)return;double seconds=(offset+player.getCurrentPosition())/1000.0,duration=(offset+player.getDuration())/1000.0;request("/api/tv-native/progress","PUT",object("id",playingId,"episode",playingEpisode,"seconds",seconds,"duration",Math.max(seconds,duration)),r->{});}
 private javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("mythic-reverie-tv")){KeyGenerator gen=KeyGenerator.getInstance("AES","AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder("mythic-reverie-tv",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return(javax.crypto.SecretKey)store.getKey("mythic-reverie-tv",null);}
 private void saveToken(String value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());cipher.updateAAD(base.getBytes("UTF-8"));prefs.edit().putString("tokenServer",base).putString("token",Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(value.getBytes("UTF-8")),Base64.NO_WRAP)).apply();}
 private String readToken()throws Exception{String saved=prefs.getString("token","");if(saved.isEmpty()||!base.equals(prefs.getString("tokenServer","")))return "";String[] parts=saved.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));cipher.updateAAD(base.getBytes("UTF-8"));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),"UTF-8");}
 @Override public void onBackPressed(){if(player!=null){saveProgress();player.release();player=null;if(screenKind.equals("live-player"))liveChannels("","",0);else title(playingId);}else if(screenKind.equals("pair")){welcome();}else if(screenKind.equals("login")||screenKind.equals("login-profile")){logoutLoginSession();pair();}else if(screenKind.equals("title")||screenKind.equals("settings")||screenKind.equals("search"))catalog(0);else super.onBackPressed();}
 @Override protected void onStart(){super.onStart();stopped=false;if(resumeNeeded){resumeNeeded=false;if(screenKind.equals("live-player"))liveChannels("","",0);else if(screenKind.equals("player"))title(playingId);else if(screenKind.equals("pair")){if(pairCode.isEmpty())pair();else poll();}else if(screenKind.equals("title"))title(selectedTitleId);else if(screenKind.equals("catalog"))catalog(0);else if(screenKind.equals("login-profile"))pair();}}
 @Override protected void onStop(){cancelNextEpisode();logoutLoginSession();saveProgress();stopped=true;resumeNeeded=true;screenVersion++;ui.removeCallbacksAndMessages(null);if(player!=null){player.release();player=null;}super.onStop();}
 @Override protected void onDestroy(){cancelNextEpisode();network.shutdown();artworkNetwork.shutdownNow();artworkCache.evictAll();super.onDestroy();}
